[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "weatherCompareSurface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "weatherCompareSurface",
      "value": {
        "cities": [
          {
            "name": "London, UK",
            "avgHigh": "23°C",
            "avgLow": "14°C",
            "image": "/london_skyline.jpg",
            "imageCaption": "London Skyline"
          },
          {
            "name": "Madrid, Spain",
            "avgHigh": "33°C",
            "avgLow": "20°C",
            "image": "/madrid_plaza_mayor.jpg",
            "imageCaption": "Madrid Plaza Mayor"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "weatherCompareSurface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              "headerRow",
              "summaryText",
              "comparisonTable",
              "imagesRow",
              "detailsCard",
              "actionsRow"
            ],
            "layout": {
              "padding": {
                "all": "medium"
              },
              "spacing": "large"
            }
          }
        },
        {
          "id": "headerRow",
          "type": "Row",
          "properties": {
            "children": [
              "weatherIcon",
              "titleText"
            ],
            "layout": {
              "spacing": "medium",
              "verticalAlignment": "center"
            }
          }
        },
        {
          "id": "weatherIcon",
          "type": "Icon",
          "properties": {
            "icon": "/weather_icon.png",
            "style": "primary"
          }
        },
        {
          "id": "titleText",
          "type": "Text",
          "properties": {
            "text": "July Temperature Comparison: London vs. Madrid",
            "style": "title-large"
          }
        },
        {
          "id": "summaryText",
          "type": "Text",
          "properties": {
            "text": "Here's a comparison of the average high and low temperatures for London, UK and Madrid, Spain during the month of July, based on historical climate data. Madrid generally experiences significantly warmer temperatures than London in July."
          }
        },
        {
          "id": "comparisonTable",
          "type": "Table",
          "properties": {
            "header": "tableHeader",
            "childrenBinding": "cities",
            "childTemplate": "tableRowTemplate"
          }
        },
        {
          "id": "tableHeader",
          "type": "TableRow",
          "properties": {
            "children": [
              "cityHeader",
              "highHeader",
              "lowHeader"
            ]
          }
        },
        {
          "id": "cityHeader",
          "type": "TableCell",
          "properties": {
            "child": "cityHeaderText"
          }
        },
        {
          "id": "cityHeaderText",
          "type": "Text",
          "properties": {
            "text": "City",
            "style": "label-large"
          }
        },
        {
          "id": "highHeader",
          "type": "TableCell",
          "properties": {
            "child": "highHeaderText"
          }
        },
        {
          "id": "highHeaderText",
          "type": "Text",
          "properties": {
            "text": "Average High",
            "style": "label-large"
          }
        },
        {
          "id": "lowHeader",
          "type": "TableCell",
          "properties": {
            "child": "lowHeaderText"
          }
        },
        {
          "id": "lowHeaderText",
          "type": "Text",
          "properties": {
            "text": "Average Low",
            "style": "label-large"
          }
        },
        {
          "id": "tableRowTemplate",
          "type": "TableRow",
          "properties": {
            "children": [
              "cityCell",
              "highCell",
              "lowCell"
            ]
          }
        },
        {
          "id": "cityCell",
          "type": "TableCell",
          "properties": {
            "child": "cityNameText"
          }
        },
        {
          "id": "cityNameText",
          "type": "Text",
          "properties": {
            "text": "${item.name}"
          }
        },
        {
          "id": "highCell",
          "type": "TableCell",
          "properties": {
            "child": "highTempText"
          }
        },
        {
          "id": "highTempText",
          "type": "Text",
          "properties": {
            "text": "${item.avgHigh}"
          }
        },
        {
          "id": "lowCell",
          "type": "TableCell",
          "properties": {
            "child": "lowTempText"
          }
        },
        {
          "id": "lowTempText",
          "type": "Text",
          "properties": {
            "text": "${item.avgLow}"
          }
        },
        {
          "id": "imagesRow",
          "type": "Row",
          "properties": {
            "children": [
              "londonImageColumn",
              "madridImageColumn"
            ],
            "layout": {
              "distribution": "space-evenly",
              "spacing": "medium"
            }
          }
        },
        {
          "id": "londonImageColumn",
          "type": "Column",
          "properties": {
            "children": [
              "londonImage",
              "londonCaption"
            ],
            "layout": {
              "crossAxisAlignment": "center",
              "spacing": "small"
            }
          }
        },
        {
          "id": "londonImage",
          "type": "Image",
          "properties": {
            "url": "/london_skyline.jpg",
            "alt": "London Skyline"
          }
        },
        {
          "id": "londonCaption",
          "type": "Text",
          "properties": {
            "text": "London Skyline",
            "style": "label-medium"
          }
        },
        {
          "id": "madridImageColumn",
          "type": "Column",
          "properties": {
            "children": [
              "madridImage",
              "madridCaption"
            ],
            "layout": {
              "crossAxisAlignment": "center",
              "spacing": "small"
            }
          }
        },
        {
          "id": "madridImage",
          "type": "Image",
          "properties": {
            "url": "/madrid_plaza_mayor.jpg",
            "alt": "Madrid Plaza Mayor"
          }
        },
        {
          "id": "madridCaption",
          "type": "Text",
          "properties": {
            "text": "Madrid Plaza Mayor",
            "style": "label-medium"
          }
        },
        {
          "id": "detailsCard",
          "type": "Card",
          "properties": {
            "child": "detailsColumn",
            "style": "outlined"
          }
        },
        {
          "id": "detailsColumn",
          "type": "Column",
          "properties": {
            "children": [
              "assumptionsTitle",
              "assumptionsList",
              "divider",
              "verifyTitle",
              "verifyText"
            ],
            "layout": {
              "padding": {
                "all": "medium"
              },
              "spacing": "medium"
            }
          }
        },
        {
          "id": "assumptionsTitle",
          "type": "Text",
          "properties": {
            "text": "Assumptions",
            "style": "title-medium"
          }
        },
        {
          "id": "assumptionsList",
          "type": "List",
          "properties": {
            "children": [
              "assumption1",
              "assumption2"
            ]
          }
        },
        {
          "id": "assumption1",
          "type": "ListItem",
          "properties": {
            "primary": "The data represents long-term historical averages (e.g., 30-year averages) for the month of July."
          }
        },
        {
          "id": "assumption2",
          "type": "ListItem",
          "properties": {
            "primary": "Temperatures are provided in Celsius."
          }
        },
        {
          "id": "divider",
          "type": "Divider"
        },
        {
          "id": "verifyTitle",
          "type": "Text",
          "properties": {
            "text": "How to Verify Historical Climate Data",
            "style": "title-medium"
          }
        },
        {
          "id": "verifyText",
          "type": "Text",
          "properties": {
            "text": "To obtain the most up-to-date or specific historical climate data, you can visit the official websites of national meteorological services (e.g., Met Office for the UK, AEMET for Spain) or consult reputable climate data archives."
          }
        },
        {
          "id": "actionsRow",
          "type": "Row",
          "properties": {
            "children": [
              "londonButton",
              "madridButton"
            ],
            "layout": {
              "spacing": "medium",
              "distribution": "center"
            }
          }
        },
        {
          "id": "londonButton",
          "type": "Button",
          "properties": {
            "label": "Explore London travel guides",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "parameters": {
                  "url": "https://www.visitlondon.com/"
                }
              }
            }
          }
        },
        {
          "id": "madridButton",
          "type": "Button",
          "properties": {
            "label": "Discover Madrid attractions",
            "action": {
              "functionCall": {
                "call": "openUrl",
                "parameters": {
                  "url": "https://www.esmadrid.com/en"
                }
              }
            }
          }
        }
      ]
    }
  }
]
